      figure.append(clone,el('figcaption','',record.label));mosaic.grid.append(figure);
      const tile={figure,clone,owned:copy.owned,trackKey:(record.video.srcObject?.getVideoTracks?.()||[]).map(t=>t.id).join()};mosaic.tiles.set(record.video,tile);
