  function decorateLiveLayout(stage,chat) {
    // Find the two existing branches. Neither React nodes nor videos are reparented.
    if(!stage||!chat)return;
    let main=stage;
    for(let i=0;main?.parentElement&&i<9;i++,main=main.parentElement){
      const shell=main.parentElement;
      if(shell.contains(chat)&&!main.contains(chat)){
        let chatColumn=chat;while(chatColumn.parentElement!==shell)chatColumn=chatColumn.parentElement;
        if(main===chatColumn||shell===document.body||shell.id==='root'||shell.id==='app-container')break;
        shell.dataset.pzRoomLayout='true';main.dataset.pzRoomMain='true';chatColumn.dataset.pzRoomChat='true';
        let page=shell.parentElement;
        for(let ancestor=page,depth=0;ancestor&&depth<8;ancestor=ancestor.parentElement,depth++){
          if(ancestor===document.body||ancestor.id==='root'||ancestor.id==='app-container')break;
          if(ancestor.querySelector(':scope > header[aria-label="Painel da live"]')){page=ancestor;break;}
          const exitButton=[...ancestor.querySelectorAll(':scope > div > button')].find(button=>(button.textContent||'').trim()==='Sair da sala');
          if(exitButton){page=ancestor;exitButton.parentElement.dataset.pzRoomExit='true';break;}
        }
        if(page&&page!==document.body&&page.id!=='root'&&page.id!=='app-container'){
          page.dataset.pzRoomPage='true';
          for(const child of page.children){
            if(!child.contains(shell)&&child.querySelector('[role="progressbar"]'))child.dataset.pzRoomGoal='true';
          }
          for(let bridge=shell.parentElement;bridge&&bridge!==page;bridge=bridge.parentElement)bridge.dataset.pzRoomBridge='true';
          if(page.parentElement?.children.length===1&&page.parentElement!==document.body&&page.parentElement.id!=='root'&&page.parentElement.id!=='app-container')page.parentElement.dataset.pzRoomFrame='true';
        }
        if(!theater&&!document.fullscreenElement){
          const playerHeight=stage.getBoundingClientRect().height;
          if(playerHeight>100){
            const height=`${Math.round(playerHeight+72)}px`;
            if(shell.style.getPropertyValue('--pz-room-chat-height')!==height)shell.style.setProperty('--pz-room-chat-height',height);
          }
        }
        shell.querySelector(':scope > .pz-live-support')?.remove();
        for(let p=stage.parentElement;p&&p!==main;p=p.parentElement)p.dataset.pzStageStack='true';
        break;
      }
    }
  }
  function decorateSourceDeck(stage) {
    const main=stage.closest('[data-pz-room-main]');
    if(!main)return;
    let deck=stage.parentElement;
    while(deck&&deck!==main&&!deck.querySelector('[id^="remoteUsersCamera"]'))deck=deck.parentElement;
    if(!deck||deck===main)return;
    const cards=[...new Set([...deck.querySelectorAll('[id^="remoteUsersCamera"]')].map(host=>host.closest('.MuiCard-root')||host.closest('.MuiCardContent-root')?.parentElement).filter(Boolean))];
    if(!cards.length)return;
    for(const sizeButton of deck.querySelectorAll('button[aria-label^="Tamanho do tile"]')){
      const controls=sizeButton.parentElement?.parentElement;
      if(controls&&!controls.querySelector('video'))controls.dataset.pzSourceSizes='true';
    }
    deck.dataset.pzSourceDeck='true';
    const tiles=[stage,...cards];
    deck.style.setProperty('--pz-source-count',String(Math.max(1,tiles.length-1)));
    for(const tile of tiles){
      tile.dataset.pzSourceTile='true';
      for(let p=tile.parentElement;p&&p!==deck;p=p.parentElement)p.dataset.pzSourceBridge='true';
      if(!tile.querySelector(':scope > .pz-source-focus')){
        const focus=button('Destacar esta fonte','live',event=>{},'pz-source-focus');
        focus.dataset.pzOwned='true';
        focus.addEventListener('click',event=>{
          event.preventDefault();event.stopPropagation();
          for(const item of deck.querySelectorAll('[data-pz-source-tile]')){delete item.dataset.pzSourceFeatured;item.querySelector(':scope > .pz-source-focus')?.setAttribute('aria-pressed','false');}
          tile.dataset.pzSourceFeatured='true';focus.setAttribute('aria-pressed','true');
        });
        tile.append(focus);
      }
    }
    if(!tiles.some(tile=>tile.dataset.pzSourceFeatured==='true')){stage.dataset.pzSourceFeatured='true';stage.querySelector(':scope > .pz-source-focus')?.setAttribute('aria-pressed','true');}
  }
  function setupLiveDock() {
    const stage=document.getElementById('packzin-stream-composite-player');
    if(!prefs.enabled||!stage){if(liveDock){liveDock.node.remove();liveDock=null;}delete root.dataset.pzDockReady;return;}
    // Follow the displayed source dimensions, not the monitor's aspect ratio.
    // Leave native multi-source compositions and fullscreen layouts in control.
    const visibleSources=[...stage.querySelectorAll('video')].filter(video=>video.videoWidth&&video.videoHeight&&video.getBoundingClientRect().width>80&&video.getBoundingClientRect().height>60);
    if(visibleSources.length===1){
      const ratio=visibleSources[0].videoWidth/visibleSources[0].videoHeight;
      const value=String(ratio);
      if(stage.style.getPropertyValue('--pz-source-ratio')!==value){
        stage.style.setProperty('--pz-source-ratio',value);
        stage.style.setProperty('--pz-source-width',`${ratio*72}vh`);
      }
      stage.dataset.pzSourceFit='true';
    }else delete stage.dataset.pzSourceFit;
    if(liveDock?.stage!==stage){
      liveDock?.node.remove();
      const node=el('section','pz-live-dock');node.id='pz-live-dock';node.dataset.pzOwned='true';node.setAttribute('aria-label','Controles rápidos da live');
      const audio=el('div','pz-dock-audio'),volume=el('input'),output=el('output');volume.type='range';volume.id='pz-quick-volume';volume.min='0';volume.max='200';volume.step='5';volume.setAttribute('aria-label','Volume rápido da live');output.htmlFor=volume.id;
      const mute=button('Silenciar áudio da live','volume',()=>{const s=audioSources()[0];if(s)setQuickVolume(s.value===0?s.last:0);},'pz-dock-icon');mute.querySelector('span').hidden=true;
      const label=el('label','pz-dock-volume-label','Volume');label.htmlFor=volume.id;
      audio.append(mute,label,volume,output);volume.addEventListener('input',()=>setQuickVolume(Number(volume.value)));
      const actions=el('div','pz-dock-actions');
      const mixer=button('Mixer de áudio','volume',()=>setPanel(true,true),'pz-dock-button');
      const pip=button('PiP','pip',()=>{const r=[...records.values()].find(r=>stage.contains(r.video));if(r)openSingle(r.video);},'pz-dock-button');pip.setAttribute('aria-label','Abrir vídeo principal em PiP');
      const cinema=button('Cinema','theater',()=>setTheater(!theater),'pz-dock-button');cinema.setAttribute('aria-label','Alternar modo cinema');
      const grid=button('Mosaico','grid',()=>openMosaic(false),'pz-dock-button pz-primary');grid.setAttribute('aria-label','Mosaico de todas as câmeras');
      actions.append(mixer,pip,cinema,grid);node.append(audio,actions);stage.after(node);
      liveDock={stage,node,audio,volume,output,mute,pip,cinema,grid,mixer,lastMute:null};
      if(stage.parentElement!==document.body)stage.parentElement.dataset.pzDockMount='true';
    }
    root.dataset.pzDockReady='true';
    decorateSourceDeck(stage);
    const count=records.size;
    liveDock.pip.disabled=!count;liveDock.grid.disabled=!count;liveDock.cinema.setAttribute('aria-pressed',String(theater));
    const source=audioSources()[0];liveDock.audio.hidden=!source;
    if(source){
      liveDock.volume.max=String(source.max);if(document.activeElement!==liveDock.volume)liveDock.volume.value=String(source.value);
      liveDock.volume.setAttribute('aria-label','Volume rápido de '+source.label);liveDock.volume.setAttribute('aria-valuetext',source.value+'%');liveDock.output.textContent=source.value+'%';
      const muted=source.value===0;if(liveDock.lastMute!==muted){liveDock.mute.replaceChildren(icon(muted?'mute':'volume'));liveDock.lastMute=muted;}
      liveDock.mute.setAttribute('aria-label',(muted?'Reativar':'Silenciar')+' áudio da live');
    }
  }
  function setQuickVolume(value) {
    try{const source=audioSources()[0];if(!source)return;source.set(value);liveDock.output.textContent=value+'%';liveDock.volume.value=String(value);schedule();}
    catch{notify('A fonte de áudio mudou. Abra o mixer para selecionar a fonte atual.');}
  }
  let railClipFrame=0;
  function clipSuggestionRail() {
    railClipFrame=0;
    const rail=document.getElementById('pz-suggestions-left');
    if(!rail)return;
    if(rail.parentElement?.hasAttribute('data-pz-rails-layout')){rail.style.removeProperty('clip-path');return;}
    const header=document.querySelector('.packzin-app-bar');
    const bounds=rail.getBoundingClientRect();
    const covered=Math.max(0,(header?.getBoundingClientRect().bottom||0)-bounds.top);
    // The rail lives outside React's root stacking context. Clip its covered
    // area explicitly so neither cards nor their follow buttons cover the bar.
    const clip=`inset(${Math.min(bounds.height,covered)}px -8px 0 -8px)`;
    if(rail.style.clipPath!==clip)rail.style.clipPath=clip;
  }
  function scheduleRailClip(){if(!railClipFrame)railClipFrame=requestAnimationFrame(clipSuggestionRail);}
  window.addEventListener('scroll',scheduleRailClip,{passive:true,capture:true});
  window.addEventListener('resize',scheduleRailClip,{passive:true});
  function positionSuggestionRail(rail) {
    const column=document.querySelector('[data-pz-suggestions]:not(#pz-suggestions-left)');
    const layout=column?.parentElement;
    if(layout&&layout!==document.body){
      layout.setAttribute('data-pz-rails-layout','true');
      if(rail.parentElement!==layout)layout.append(rail);
      rail.style.removeProperty('clip-path');
      return;
    }
    const header=document.querySelector('.packzin-app-bar')||document.querySelector('header');
    const headerBottom=header?.getBoundingClientRect().bottom||112;
    const top=`${Math.round(Math.max(0,headerBottom)+16)}px`;
    if(root.style.getPropertyValue('--pz-rails-top')!==top)root.style.setProperty('--pz-rails-top',top);
    if(rail.style.getPropertyValue('--pz-left-rail-top')!==top)rail.style.setProperty('--pz-left-rail-top',top);
    scheduleRailClip();
  }
  function splitSuggestionRails(suggestionColumn) {
    if(!suggestionColumn)return;
    const existing=document.getElementById('pz-suggestions-left');
    if(existing){positionSuggestionRail(existing);return;}
    const cards=[...suggestionColumn.querySelectorAll('.MuiCard-root')].filter(card=>card.querySelector('a[aria-label^="Ver perfil"]'));
    const seen=new Set();
    const unique=cards.filter(card=>{
      const link=card.querySelector('a[aria-label^="Ver perfil"]');
      const href=link?.getAttribute('href');
      if(!href || seen.has(href))return false;
      seen.add(href); return true;
    });
    if(unique.length<4)return;
    const left=document.createElement('aside');
    left.id='pz-suggestions-left';
    left.dataset.pzSuggestions='true';
    left.setAttribute('aria-label','Mais criadores para seguir');
    const title=document.createElement('h3');
    title.textContent='Mais criadores';
    left.append(title);
    const moveCount=Math.ceil(unique.length/2);
    for(const card of unique.slice(0,moveCount))left.append(card);
    // The host does not use a stable <main> element on every feed variant.
    // A body-level rail keeps the rail independent from that changing grid.
    document.body.append(left);
    positionSuggestionRail(left);
    suggestionColumn.dataset.pzRailsReady='true';
  }
  function decorateFollowedUpdates(feedRoot) {
    const tab=[...document.querySelectorAll('[role="tab"],.MuiTab-root')].find(n=>{
      const label=n.cloneNode(true);
      label.querySelectorAll('.pz-followed-new').forEach(b=>b.remove());
      return label.textContent.trim()==='Quem eu sigo';
    });
    if(!tab||!feedRoot)return;
    const active=tab.getAttribute('aria-selected')==='true'||tab.classList.contains('Mui-selected');
    // Other tabs reuse the feed container. Their posts are not followed updates.
    const panelId=tab.getAttribute('aria-controls');
    const panel=panelId?document.getElementById(panelId):null;
    const ownsPanel=tab.id&&panel?.getAttribute('role')==='tabpanel'&&panel.getAttribute('aria-labelledby')===tab.id;
    const followedRoot=active?feedRoot:(ownsPanel?panel:null);
    const getSignature=card=>{
      const post=card.querySelector('a[href*="/post/"],a[href*="/publicacao/"],a[href*="/feed/"]');
      // A profile identifies an author, not a publication.
      return post?.getAttribute('href')||'';
    };
    const signatures=followedRoot?[...followedRoot.querySelectorAll('.MuiCard-root')].map(getSignature).filter(Boolean):[];
    const markSeen=items=>{
      let changed=false;
      for(const sig of items)if(!followedSeen.has(sig)){followedSeen.add(sig);changed=true;}
      if(changed)try{localStorage.setItem(FOLLOWED_SEEN_STORE,JSON.stringify([...followedSeen].slice(-300)));}catch{}
    };
    // Keep the current snapshot on the live tab: React can replace the feed root.
    tab.pzFollowedSignatures=signatures;
    if(active)markSeen(signatures);
    const unseen=signatures.filter(sig=>!followedSeen.has(sig));
    let badge=tab.querySelector('.pz-followed-new');
    if(unseen.length&&!badge&&!active){badge=document.createElement('span');badge.className='pz-followed-new';badge.setAttribute('aria-label','Novidades de quem você segue');badge.textContent='NOVO';tab.append(badge);}
    if(!unseen.length||active)badge?.remove();
    if(tab.dataset.pzFollowedBound==='true')return;
    tab.dataset.pzFollowedBound='true';
    tab.addEventListener('click',()=>{
      markSeen(tab.pzFollowedSignatures||[]);
      tab.querySelector('.pz-followed-new')?.remove();
    },{passive:true,capture:true});
  }
  function isRoomVideo(video) {
    return /^\/discord\/[^/]+/.test(location.pathname)&&!!video.closest('#packzin-stream-composite-player,[data-packzin-live-meeting]');
  }
  const chatObservers=new Map();
  function clearChatObservers(all=false) {
    for(const [thread,state] of chatObservers)if(all||!thread.isConnected){
      state.observer.disconnect();clearTimeout(state.timer);chatObservers.delete(thread);
    }
  }
  function decorateLiveChat(chat) {
    if(!chat)return;
    chat.dataset.pzLiveChatEnhanced='true';
    const viewerCount=[...chat.querySelectorAll('span')].find(node=>/\d+\s*assistindo/i.test(node.textContent||''));
    if(viewerCount){
      viewerCount.dataset.pzViewersTrigger='true';
      viewerCount.setAttribute('role','button');viewerCount.setAttribute('tabindex','0');
      viewerCount.title='Ver quem está participando da live';
      if(viewerCount.dataset.pzViewersBound!=='true'){
        const showParticipants=()=>{
          const excluded=/^(carregar|chat flutuante|presente|gorjeta|roleta|adicionar|enviar|ver novas|abrir)/i;
          const thread=chat.querySelector('[data-pz-chat-thread]');
          const names=[...chat.querySelectorAll('[data-pz-chat-thread] button, [role="log"] button, [role="feed"] button')]
            .map(node=>(node.getAttribute('aria-label')||node.textContent||'').trim())
            .filter(name=>name&&!excluded.test(name)&&!/^\d+/.test(name)&&name.length<80);
          const streamer=[...document.querySelectorAll('a[href*="/perfil/"]')].find(link=>/streamer|perfil do/i.test(link.textContent||'')||link.closest('[data-pz-room-main]'))?.textContent?.trim();
          if(streamer)names.push(streamer.replace(/^@/,''));
          const unique=[...new Set(names)].map(name=>({name,href:`/perfil/${encodeURIComponent(name.replace(/^@/,''))}`}));
          openParticipantsWindow(`room-participants:${location.pathname}`,unique);
        };
        viewerCount.addEventListener('click',showParticipants);viewerCount.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();showParticipants();}});viewerCount.dataset.pzViewersBound='true';
      }
    }
    const popout=[...chat.querySelectorAll('button')].find(button=>/chat flutuante/i.test(button.textContent||''));
    if(popout){popout.dataset.pzChatPopout='true';popout.setAttribute('aria-label','Abrir chat em janela flutuante');popout.title='Abrir chat em janela flutuante';}
    // Only the support actions at the bottom of the chat receive this treatment.
    // The tabs also contain "Presentes" and "Roleta" and must keep their native layout.
    for(const payment of chat.querySelectorAll('[data-pz-chat-payment]'))delete payment.dataset.pzChatPayment;
    for(const label of ['Presente na live','Gorjeta na live']){
      const payment=[...chat.querySelectorAll('button')].find(button=>button.getAttribute('aria-label')===label);
      if(payment)payment.dataset.pzChatPayment='true';
    }
    const composer=chat.querySelector('textarea,[contenteditable="true"],input[placeholder*="mensagem" i]');
    const composerShell=composer?.closest('form')||composer?.parentElement;
    if(composerShell)composerShell.dataset.pzChatComposer='true';
    for(const link of chat.querySelectorAll('a[href*="/perfil/"]'))link.dataset.pzChatProfile='true';
    const cachedThread=chat.querySelector('[data-pz-chat-thread]');
    const scrollAreas=cachedThread?[cachedThread]:[...chat.querySelectorAll('div,[role="log"],[role="feed"]')].filter(node=>{
      if(node.contains(composer)||node.clientHeight===0)return false;
      return /auto|scroll/.test(getComputedStyle(node).overflowY)&&!node.closest('.MuiTabs-root')&&(node.querySelector('.MuiAvatar-root')||node.getAttribute('role')==='log'||node.getAttribute('role')==='feed');
    });
    const thread=scrollAreas.sort((a,b)=>b.scrollHeight-a.scrollHeight)[0];
    if(!thread)return;
    for(const old of chat.querySelectorAll('[data-pz-chat-thread]'))if(old!==thread)delete old.dataset.pzChatThread;
    thread.dataset.pzChatThread='true';
    if(!chatObservers.has(thread)){
      const state={timer:0,observer:null};
      state.observer=new MutationObserver(changes=>{
        if(document.hidden||state.timer||!changes.some(change=>!change.target.closest?.('[data-pz-owned]')))return;
        state.timer=setTimeout(()=>{state.timer=0;if(thread.isConnected&&prefs.enabled&&!document.hidden)decorateLiveChat(chat);},150);
      });
      state.observer.observe(thread,{childList:true,subtree:true});
      chatObservers.set(thread,state);
    }
    for(let parent=thread.parentElement;parent&&parent!==chat;parent=parent.parentElement)parent.dataset.pzChatFlow='true';
    const messages=[...thread.children].filter(node=>node.querySelector?.('.MuiAvatar-root')&&node.textContent.trim());
    let previous='';
    for(const message of messages){
      message.dataset.pzChatMessage='true';
      const author=message.querySelector('a[href*="/perfil/"], [class*="username" i], [class*="author" i]')?.textContent?.trim()||'';
      if(author&&author===previous)message.dataset.pzChatContinuation='true';else delete message.dataset.pzChatContinuation;
      previous=author||previous;
    }
    let latest=chat.querySelector('.pz-chat-new-button');
    if(latest&&latest.parentElement!==thread){latest.remove();latest=null;}
    if(!latest){
      latest=button('Ver novas mensagens','chat',()=>{thread.scrollTo({top:thread.scrollHeight,behavior:'smooth'});},'pz-chat-new-button');
      latest.querySelector('.pz-button-label').textContent='Novas mensagens';latest.hidden=true;
      thread.addEventListener('scroll',()=>{latest.hidden=thread.scrollTop+thread.clientHeight>=thread.scrollHeight-28;},{passive:true});
    }
    // It belongs to the message scroller, never over the composer or support controls.
    if(latest.parentElement!==thread)thread.append(latest);
    latest.hidden=thread.scrollTop+thread.clientHeight>=thread.scrollHeight-28;
  }
  function decorateLiveMonetization(chat) {
    if(!chat)return;
    // Preserve native support actions; mark once instead of clearing/rebuilding.
    const actionFor=(label,name)=>{
      const button=[...chat.querySelectorAll('button')].find(node=>node.getAttribute('aria-label')===label);
      if(!button)return;
      button.dataset.pzLiveSupportAction=name;
      if(name==='wheel'){
        button.dataset.pzLiveWheelNative='true';
        button.title='Abrir a roleta oficial desta live';
      }
    };
    actionFor('Presente na live','gift');actionFor('Gorjeta na live','tip');actionFor('Roleta na live','wheel');
    for(const tab of chat.querySelectorAll('[role="tab"]')){
      const name=(tab.textContent||'').trim();
      const action=name==='Presentes'?'gift':name==='Roleta'?'wheel':null;
      if(action&&chat.querySelector(`[data-pz-live-support-action="${action}"]`)){
        if(tab.getAttribute('aria-selected')==='true')chat.querySelector('[role="tab"]')?.click();
        tab.dataset.pzSupportDuplicate='true';
      }
    }
    for(const dialog of document.querySelectorAll('[role="dialog"]')){
      if(/roleta|wheel/i.test(dialog.textContent||''))dialog.dataset.pzLiveWheelDialog='true';
    }
  }
  function decorateLiveDirectory() {
    const hero=document.querySelector('[aria-labelledby="discord-hero-title"]');
    if(!hero)return;
    hero.dataset.pzLiveDirectoryHero='true';
    if(!hero.querySelector('.pz-live-hero-icon')){const heroIcon=icon('live');heroIcon.classList.add('pz-live-hero-icon');hero.prepend(heroIcon);}
    const directory=hero.parentElement;if(directory)directory.dataset.pzLiveDirectory='true';
    directory?.querySelector('.pz-live-value-strip')?.remove();
    const filters=document.querySelector('[aria-label="Filtrar salas"]');
    if(filters)filters.parentElement.dataset.pzLiveDirectoryFilters='true';
    const cards=[...document.querySelectorAll('.MuiCard-root')].filter(card=>card.querySelector('[aria-label$=" viewers"]'));
    if(!cards.length)return;
    for(const card of cards){
      card.dataset.pzLiveCard='true';
      const content=card.querySelector('.MuiCardContent-root');
      if(!content)continue;
      const host=content.querySelector('a[aria-label^="Ver perfil de"]');
      const hostName=host?.getAttribute('aria-label')?.replace(/^Ver perfil de\s*/i,'').trim();
      const source=[...content.children].find(node=>node.tagName==='DIV'&&node.querySelector('.MuiAvatar-root img'));
      if(!source)continue;
      source.dataset.pzLiveParticipantSource='true';
      const people=[{name:hostName,href:host?.getAttribute('href')},...[...source.querySelectorAll('.MuiAvatar-root')].map(node=>{const name=node.getAttribute('title')||node.querySelector('img')?.alt||'';return {name,href:`/perfil/${encodeURIComponent(name.replace(/^@/,''))}`};})].filter(person=>person.name&&person.href).filter((person,index,all)=>all.findIndex(other=>other.name===person.name)===index);
      const signature=people.map(person=>`${person.name}|${person.href}`).join('|');
      if(card.dataset.pzParticipantsSignature===signature)continue;
      card.dataset.pzParticipantsSignature=signature;
      content.querySelector('.pz-live-participants')?.remove();
      content.querySelector('.pz-live-participants-trigger')?.remove();
      const trigger=button(`Ver ${people.length} ${people.length===1?'participante':'participantes'} da sala`,'profile',()=>openParticipantsWindow(`participants:${host?.getAttribute('href')||card.querySelector('h3')?.textContent||sequence}`,people),'pz-live-participants-trigger');
      trigger.querySelector('.pz-button-label').textContent=`${people.length} ${people.length===1?'pessoa na sala':'pessoas na sala'}`;
      for(const type of ['pointerdown','click'])trigger.addEventListener(type,event=>event.stopPropagation());
      content.append(trigger);
    }
    const gridWrap=cards[0].closest('.MuiGrid-container');
    const gridItems=cards.map(card=>card.parentElement).filter(Boolean);
    if(gridWrap&&gridItems.length===cards.length&&gridItems.every(item=>item.parentElement===gridWrap)){
      gridWrap.dataset.pzLiveDirectoryGrid='true';
      for(const item of gridItems)item.dataset.pzLiveGridItem='true';
    }
    if(gridWrap)gridWrap.dataset.pzLiveDirectoryWrap='true';
    if(directory&&gridWrap&&!directory.querySelector('.pz-live-section-heading')){
      const heading=el('div','pz-live-section-heading');heading.append(icon('spark'),el('h2','','Salas em destaque'),el('span','','Encontre gente para jogar e conversar'));
      gridWrap.before(heading);
    }
  }
  function decorateGameplayDirectory() {
    const marketplace=document.querySelector('[data-testid="gameplay-marketplace"]');
    if(!marketplace)return;
    const main=marketplace.closest('main');if(main)main.dataset.pzGameplay='true';
    marketplace.dataset.pzGameplayMarketplace='true';
    const hero=document.querySelector('[data-testid="gameplay-hero"]');if(hero)hero.dataset.pzGameplayHero='true';
    const searchBar=marketplace.querySelector('[data-testid="gameplay-discover-bar"]');if(searchBar)searchBar.dataset.pzGameplaySearchBar='true';
    const nativeFilter=marketplace.querySelector('[data-testid="gameplay-discover-filters-open"]');if(nativeFilter)nativeFilter.dataset.pzGameplayNativeFilter='true';
    const chipBar=marketplace.querySelector('[aria-label="Filtrar por jogo"]');if(chipBar)chipBar.dataset.pzGameplayGameChips='true';
    const cards=[...marketplace.querySelectorAll('[data-testid="gameplay-seller-card"]')];
    const grid=cards[0]?.parentElement;if(grid&&cards.every(card=>card.parentElement===grid))grid.dataset.pzGameplayGrid='true';
    for(const card of cards)card.dataset.pzGameplayCard='true';
    if(chipBar&&!marketplace.querySelector('.pz-game-chips-controls')){
      const controls=el('div','pz-game-chips-controls');
      const previous=button('Ver jogos anteriores','close',()=>chipBar.scrollBy({left:-Math.max(260,chipBar.clientWidth*.65),behavior:'smooth'}),'pz-game-chips-arrow');
      const next=button('Ver próximos jogos','spark',()=>chipBar.scrollBy({left:Math.max(260,chipBar.clientWidth*.65),behavior:'smooth'}),'pz-game-chips-arrow');
      previous.querySelector('.pz-button-label').textContent='‹';next.querySelector('.pz-button-label').textContent='›';controls.append(previous,next);chipBar.before(controls);
    }
    const availableHeading=[...marketplace.querySelectorAll('h2,h3')].find(heading=>/Criadoras disponíveis agora/i.test(heading.textContent));
    if(availableHeading)availableHeading.dataset.pzGameplayAvailableHeading='true';
    marketplace.querySelector('.pz-gameplay-today')?.remove();
    for(const card of cards){
      const cta=card.querySelector('[data-testid="gameplay-seller-view-options"]');
      const label=cta?.querySelector('.MuiButton-label');
      if(cta&&label&&label.textContent!=='Jogar agora'&&/Disponível agora/i.test(card.textContent||'')){if(!cta.dataset.pzOriginalLabel)cta.dataset.pzOriginalLabel=label.textContent;label.textContent='Jogar agora';}
    }
  }
  function decorateDiscoverySurfaces() {
    // Identify native sections by their controls, never generated JSS names.
    const search=document.getElementById('feed-search-input');
    if(search){
      let feed=[...document.querySelectorAll('[data-pz-feed]')][0];
      if(!feed){
        for(let p=search.parentElement,depth=0;p&&depth++<9;p=p.parentElement){
          if(p.querySelector('[aria-label="feed tabs"]')){feed=p;feed.dataset.pzFeed='true';break;}
        }
      }
      if(feed){
        for(const child of feed.children){
          if(child.contains(search))child.dataset.pzFeedSearchBlock='true';
          if(child.querySelector('[aria-label="Stories"]'))child.dataset.pzFeedStoriesBlock='true';
          if(child.querySelector('[aria-label="feed tabs"]'))child.dataset.pzFeedActionsBlock='true';
        }
        const tabs=feed.querySelector('[aria-label="feed tabs"]');
        const actions=tabs?.closest('[data-pz-feed-actions-block]');
        const posts=actions?.nextElementSibling;
        if(posts){posts.dataset.pzFeedPosts='true';const grid=posts.querySelector(':scope > .MuiGrid-container');if(grid)grid.dataset.pzFeedPostsGrid='true';}
        let column=feed.closest('.MuiGrid-item');
        for(let node=feed;node&&node.parentElement;node=node.parentElement){
          if(node.parentElement.matches('[data-pz-rails-layout]')){column=node;break;}
        }
        if(column)column.dataset.pzFeedColumn='true';
      }
    }
    if(search){
      const row=search.closest('.MuiFormControl-root')?.parentElement?.parentElement;
      if(row?.querySelector('button[aria-label="Buscar"]'))row.dataset.pzFeedSearchRow='true';
    }
    const explore=document.querySelector('input[aria-label="buscar no explorar v2"]');
    if(explore){
      let hero=explore.parentElement;
      for(let depth=0;hero&&depth<7;depth++,hero=hero.parentElement){
        if(!hero.querySelector(':scope > h3'))continue;
        hero.dataset.pzExploreIntro='true';
        const banner=hero.parentElement;
        banner.dataset.pzExploreHero='true';
        if(banner.parentElement?.querySelector('[aria-label="Nível de experiência"]'))banner.parentElement.dataset.pzExplorePage='true';
        break;
      }
    }
  }
  function decoratePage() {
    decorateNavigation();
    const livePage=isLivePage();
    const suggestionTitle=[...document.querySelectorAll('h2,h3')].find(n=>n.textContent.trim()==='Sugestões para seguir');
    const suggestionColumn=suggestionTitle?.closest('.MuiGrid-grid-sm-3')||suggestionTitle?.parentElement?.parentElement?.parentElement;
    if(suggestionColumn){suggestionColumn.dataset.pzSuggestions='true';suggestionColumn.setAttribute('aria-label','Sugestões para seguir');}
    if(!suggestionColumn)document.getElementById('pz-suggestions-left')?.remove();
    if(suggestionColumn)for(const link of suggestionColumn.querySelectorAll('a[aria-label^="Ver perfil"]')){
      if(link.dataset.pzProfileBound==='true')continue;
      link.dataset.pzProfileBound='true';
      link.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();const label=(link.getAttribute('aria-label')||'').replace(/^Ver perfil de\s*/i,'').trim()||'Perfil';openFloatingPage('profile:'+link.getAttribute('href'),label,link);});
    }
    splitSuggestionRails(suggestionColumn);
    const search=document.getElementById('feed-search-input')||document.querySelector('input[name="feed-search-input"]');
    decorateDiscoverySurfaces();
    decorateFollowedUpdates(search?.closest('[data-pz-feed]')||document.querySelector('[data-pz-feed]'));
    if(isGameplayPage())decorateGameplayDirectory();
    if(search)for(let p=search.parentElement, depth=0;p&&depth++<7;p=p.parentElement)if(p.querySelector('[aria-label="feed tabs"]')){p.dataset.pzFeed='true';break;}
    if(livePage) {
      decorateLiveDirectory();
      for(const card of document.querySelectorAll('.MuiCard-root'))if(card.querySelector('[aria-label$=" viewers"]'))card.dataset.pzLiveCard='true';
      const tabs=document.querySelector('[aria-label="Seções da live"]');
      const chat=tabs?.closest('aside')||tabs?.closest('.MuiCard-root');if(chat){chat.dataset.pzChat='true';decorateLiveChat(chat);decorateLiveMonetization(chat);}
      const stage=document.getElementById('packzin-stream-composite-player')||originalSettingsButton()?.parentElement?.parentElement;
      if(stage){stage.dataset.pzLiveStage='true';const column=stage.closest('.MuiGrid-item');if(column)column.dataset.pzLiveMain='true';}
      decorateLiveLayout(stage,chat);
      if(theater)setTheater(true);
    }
  }
  let cameraSignature='';
  function updatePanel() {
    if(panel.hidden)return;
    const list=[...records.values()];mosaicButton.disabled=!list.length;floatButton.disabled=!list.length;
    theaterButton.hidden=!isLivePage();theaterButton.setAttribute('aria-pressed',String(theater));
    const signature=list.map(r=>r.id+':'+r.label).join('|');
    if(signature!==cameraSignature){cameraSignature=signature;cameraList.replaceChildren();
      for(const r of list)cameraList.append(button(`PiP · ${r.label}`,'pip',()=>openSingle(r.video),'pz-action'));
    }
    renderAudio();
  }
  function scan() {
    scheduled=0;
    if(document.hidden)return;
    clearChatObservers();
    // Switching Seguro/+18 replaces a large part of the host page. Let that
    // render settle before querying and decorating it again.
    if(Date.now()<experienceSwitchUntil){schedule();return;}
    // Keep a lightweight Personalizar entry in the native header even when
    // the user disabled the visual layer, so reactivation remains discoverable
    // after a full reload as well as immediately after clicking the toggle.
    if(!prefs.enabled){
      decorateNavigation();
      if(navigation){navigation.bar.hidden=true;navigation.spacer.hidden=true;navigation.appearance.hidden=false;}
      applyTheme();
      return;
    }
    if(lastRoute!==location.pathname){lastRoute=location.pathname;closeMosaic();setTheater(false);}
    applyTheme();decoratePage();
    for(const record of [...records.values()])if(!isRoomVideo(record.video)||!available(record.video)||!record.bar.isConnected)removeRecord(record);
    for(const video of document.querySelectorAll('#packzin-stream-composite-player video,[data-packzin-live-meeting] video'))if(isRoomVideo(video)&&available(video)&&!records.has(video))registerVideo(video);
    for(const r of records.values()) {
      r.bar.classList.toggle('pz-small',r.host.clientWidth<440);
      r.pip.setAttribute('aria-pressed',String(document.pictureInPictureElement===r.video));
    }
    setupLiveDock();reconcileMosaic();updatePanel();
  }
  function schedule() {
    if(scheduled||!prefs.enabled||document.hidden)return;
    const wait=Math.max(300,experienceSwitchUntil-Date.now()+40);
    scheduled=setTimeout(scan,wait);
  }
