    for(const attr of ['data-pz-room-page','data-pz-room-frame','data-pz-room-bridge','data-pz-room-exit','data-pz-room-goal'])for(const node of document.querySelectorAll(`[${attr}]`))node.removeAttribute(attr);
    document.querySelectorAll('[data-pz-chat-flow]').forEach(node=>delete node.dataset.pzChatFlow);
    document.querySelectorAll('.pz-live-support').forEach(node=>node.remove());
